import{_ as t,c as i,o as n,ag as a}from"./chunks/framework.CQuhCYrb.js";const m=JSON.parse('{"title":"Guide to Unmanned Systems","description":"","frontmatter":{"title":"Guide to Unmanned Systems"},"headers":[],"relativePath":"general/guide-to-unmanned-systems.md","filePath":"general/guide-to-unmanned-systems.md","lastUpdated":null}'),o={name:"general/guide-to-unmanned-systems.md"};function s(r,e,l,d,h,c){return n(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="guide-to-unmanned-systems" tabindex="-1">Guide to Unmanned Systems <a class="header-anchor" href="#guide-to-unmanned-systems" aria-label="Permalink to &quot;Guide to Unmanned Systems&quot;">​</a></h1><h2 id="leader-s-guide-to-unmanned-systems" tabindex="-1">Leader&#39;s Guide to Unmanned Systems <a class="header-anchor" href="#leader-s-guide-to-unmanned-systems" aria-label="Permalink to &quot;Leader&#39;s Guide to Unmanned Systems&quot;">​</a></h2><p>Return back to <a href="/general/unmanned-systems.html">Unmanned Systems</a></p><h3 id="training-for-subordinates" tabindex="-1">Training for Subordinates <a class="header-anchor" href="#training-for-subordinates" aria-label="Permalink to &quot;Training for Subordinates&quot;">​</a></h3><h3 id="unmanned-systems-dealing-with-vendors" tabindex="-1">Unmanned Systems: Dealing with Vendors <a class="header-anchor" href="#unmanned-systems-dealing-with-vendors" aria-label="Permalink to &quot;Unmanned Systems: Dealing with Vendors&quot;">​</a></h3><p>This section is not intended to call out any specific vendor but to help leaders identify attributes and aspects that have been problematic in the past.</p><blockquote><p>[insert unit org or other] requires an unmanned system that ensures modularity and open architecture for easy modifications and upgrades, with capabilities such as auto-frequency switching and hardened GPS-Rx for robust operation against jamming. The system must be day/night capable, support swappable communication modules, and run on a non-proprietary operating system and backend to avoid vendor lock-in and ensure compatibility. The imaging system should be shutterless for continuous capture, and the design must be built-for-purpose, tailored to [insert specific mission needs]. Maintenance and repair should be feasible in-house, with minimal reliance on vendor-specific services. The system must demonstrate proven performance in challenging environments and be equipped with effective security measures against electronic warfare threats.</p></blockquote><h3 id="swap-c-comparison-table-for-unmanned-systems" tabindex="-1">SWaP-C Comparison Table for Unmanned Systems <a class="header-anchor" href="#swap-c-comparison-table-for-unmanned-systems" aria-label="Permalink to &quot;SWaP-C Comparison Table for Unmanned Systems&quot;">​</a></h3><p><strong>SWaP-C</strong>: Size, Weight, Power, Cost</p><table tabindex="0"><thead><tr><th>Model</th><th>Size</th><th>Weight</th><th>Power</th><th>Cost</th><th>Point of Contact</th><th>Remarks</th></tr></thead><tbody><tr><td>Model A</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Model B</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Model C</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Model D</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Model E</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>SWAP-C Table Key:</strong></p><ul><li><strong>Size</strong>: Dimensions of the drone (e.g., L x W x H)</li><li><strong>Weight</strong>: Total weight of the drone including payload (in kg or lbs)</li><li><strong>Power</strong>: Power requirements and battery life (e.g., watts, hours of operation)</li><li><strong>Cost</strong>: Total cost of the drone (including maintenance and operation costs)</li><li><strong>Point of Contact</strong>: The primary contact person for the drone vendor</li><li><strong>Remarks</strong>: Additional notes or comments about the drone&#39;s performance, capabilities, and limitations.</li></ul><h3 id="key-phrases-to-watch-for" tabindex="-1">Key Phrases to Watch For <a class="header-anchor" href="#key-phrases-to-watch-for" aria-label="Permalink to &quot;Key Phrases to Watch For&quot;">​</a></h3><h4 id="look-for-good" tabindex="-1">Look For (Good) <a class="header-anchor" href="#look-for-good" aria-label="Permalink to &quot;Look For (Good)&quot;">​</a></h4><ul><li><strong>Modularity and Open Architecture</strong>: Important for flexibility and ease of maintenance. <ul><li>Example: There are commercial UUVs where overturning a screw can lead to 6 weeks of downtime and a $30,000 fix, which must be done by the vendor.</li></ul></li><li><strong>Auto-frequency Switching</strong>: Indicates advanced capability for frequency management.</li><li><strong>Hardened GPS-Rx</strong>: Suggests robustness against GPS jamming.</li><li><strong>Day/Night Capable</strong>: Implies versatility in various lighting conditions.</li><li><strong>Swappable Comms</strong>: Indicates modular communication systems.</li><li><strong>Non-Proprietary OS/Back End</strong>: Avoids vendor lock-in and promotes compatibility. <ul><li>Easily updatable firmware, software, and a DevSecOps pipeline dedicated to continually pushing out patches… timeline of weeks, not years.</li></ul></li><li><strong>Shutterless</strong>: Refers to continuous image capture capability.</li><li><strong>Built-for-Purpose</strong>: Custom solutions tailored for specific needs. <ul><li>&quot;comes with 5 batteries&quot; or &quot;runs on diesel&quot;</li><li>&quot;prisoners are using our platform to drop drugs that&#39;s how hard it is to detect&quot;</li><li>&quot;we can reconstitute faster than they can reconstitute the countermeasure&quot; (these are the terms of the new DIB arms race!)</li></ul></li></ul><h4 id="sounds-good-but" tabindex="-1">Sounds Good But... <a class="header-anchor" href="#sounds-good-but" aria-label="Permalink to &quot;Sounds Good But...&quot;">​</a></h4><ul><li><strong>GPS</strong>: As for navigation in a GPS denied environment, it&#39;s nice to have, but I haven&#39;t seen it work too well. Buildings, city blocks, treelines, hell, whole patches of forest I have seen completely disappear over the course of a few hours.</li></ul><h4 id="watch-out-for-bad" tabindex="-1">Watch Out For (Bad) <a class="header-anchor" href="#watch-out-for-bad" aria-label="Permalink to &quot;Watch Out For (Bad)&quot;">​</a></h4><ul><li><strong>Proprietary Systems</strong>: Buzzwords indicating a lack of flexibility and potential vendor lock-in.</li><li><strong>With enough Time and Resources we can do xyz</strong>: Anyone could and does say this and is a pretty easy cop out to detect.</li><li><strong>Unjammable UAS</strong>: Any company claiming their UAS is unjammable.</li><li><strong>Future Features</strong>: Phrases like &quot;*** feature to be implemented Q4&quot;.</li><li><strong>Firm Fixed Cost Plus</strong>: Potential hidden costs.</li><li><strong>Special Price</strong>: &quot;My friend, special price for you my friend.&quot;</li><li><strong>EW-proof</strong>: Claims of being electronic warfare-proof without evidence.</li><li><strong>Tested in Battlefield Conditions of Kyiv, Ukraine</strong>: Kyiv is like bragging about being at KAIA or Bagram or Erbil, not necessarily indicative of quality. <ul><li>&quot;An island in the pacific.&quot; Which island? Here&#39;s a pen. Touch the map. Draw an icon. Now tell me what USCT will say.</li></ul></li></ul><h3 id="questions-leaders-should-be-asking" tabindex="-1">Questions Leaders Should Be Asking <a class="header-anchor" href="#questions-leaders-should-be-asking" aria-label="Permalink to &quot;Questions Leaders Should Be Asking&quot;">​</a></h3><ol><li>How does the system ensure modularity and open architecture?</li><li>Can you provide examples of how the system can be easily modified or upgraded?</li><li>What are the specific capabilities and limitations of the system in terms of auto-frequency switching and hardened GPS-Rx?</li><li>Is the system day/night capable, and can you provide details on its performance in various lighting conditions?</li><li>Does the system support swappable communication modules?</li><li>Can you demonstrate the process of swapping out comms?</li><li>What operating system and backend does the system use?</li><li>Is it non-proprietary, and how easily can it be integrated with other systems?</li><li>Is the imaging system shutterless, and how does this benefit continuous image capture?</li><li>Is the system built-for-purpose, or is it designed to be a general-purpose solution?</li><li>Can you provide case studies where the system was used for specific missions?</li><li>How does the system handle maintenance and repair?</li><li>Are there any vendor-specific maintenance requirements?</li><li>Can we perform basic maintenance and repairs in-house?</li><li>What are the security measures in place to protect the system from electronic warfare (EW) threats?</li><li>How has the system been tested against EW threats?</li><li>Can you provide real-world examples or case studies of the system&#39;s performance in challenging environments, such as adverse weather conditions?</li><li>What are the total costs associated with the system, including hidden costs?</li><li>Are there any firm fixed cost plus arrangements?</li><li>What is the expected lifespan of the system, and what are the maintenance requirements over its lifespan?</li><li>What kind of support and service do you offer post-purchase?</li><li>Can you provide details on your customer support and service level agreements (SLAs)?</li><li>Have any of your systems been tested in battlefield conditions?</li><li>If so, can you provide specific locations and details on the testing environment?</li><li>How does this system work in the total absence of links to SVs - no GNSS, no Starlink, etc?</li><li>What is the CE90 of this system, under such conditions?</li><li>What does end-game look like for this system? How does it guide to target?</li></ol><p><strong>PACOM specific use cases - Explain the concept of employment:</strong></p><ul><li>Emphasis on survival v. known threats and geopolitical realities of whatever land is involved in the CONEMP.</li><li>What agreements do we currently have with that country?</li><li>What have they said about their willingness to allow us to use their land in use cases that don&#39;t directly involve their own territorial integrity?</li></ul><h3 id="actions-for-technical-section-or-consultant-to-validate-suas-claims" tabindex="-1">Actions for Technical Section or Consultant to Validate SUAS Claims <a class="header-anchor" href="#actions-for-technical-section-or-consultant-to-validate-suas-claims" aria-label="Permalink to &quot;Actions for Technical Section or Consultant to Validate SUAS Claims&quot;">​</a></h3><ul><li><strong>EW Testing</strong>: Bring in EW aggressors to attempt to break the system. Use basic TTPs found in Ukraine and see if the system passes.</li><li><strong>Field Testing</strong>: Test the system in real-world conditions, including challenging environments and battlefield conditions, to ensure reliability and performance.</li><li><strong>Hardware and Software Validation</strong>: Ensure the system&#39;s hardware and software are as barebones as possible to reduce failure points. Verify the claimed functionalities, such as GPS hardening and auto-frequency switching.</li><li><strong>Signal Resilience</strong>: Test the system&#39;s ability to operate without GPS and in the presence of signal jamming and spoofing.</li><li><strong>Maintenance and Repair</strong>: Validate that maintenance and repair can be performed in-house and are not overly reliant on vendor-specific services.</li><li><strong>Cost Analysis</strong>: Conduct a thorough cost analysis to uncover any hidden costs and verify the total cost of ownership, including maintenance and upgrades.</li><li><strong>Integration Testing</strong>: Test the integration of the system with existing technology and workflows to ensure compatibility and ease of use.</li><li><strong>Performance Metrics</strong>: Establish and measure key performance metrics, such as CE90, to validate the system&#39;s accuracy and effectiveness in various conditions.</li></ul><h3 id="telltale-signs-leaders-should-be-aware-of" tabindex="-1">Telltale Signs Leaders Should Be Aware Of <a class="header-anchor" href="#telltale-signs-leaders-should-be-aware-of" aria-label="Permalink to &quot;Telltale Signs Leaders Should Be Aware Of&quot;">​</a></h3><p><strong>Modularity and Open Architecture:</strong></p><ul><li>Commercial UUVs might have stringent vendor-dependent maintenance requirements, such as a $30,000 fix for overturning a screw, which can result in 6 weeks of downtime.</li><li>Similar to the &quot;John Deere problem,&quot; where maintenance and part replacements are highly controlled by the vendor.</li><li>Around 60% of the parts in expendable UUV electronics are sourced from the air market to allow resourcing and repurposing from the air wing depot.</li><li>Lack of knowledge or focus on robotics/theory by company leadership, instead emphasizing product and marketing.</li><li>High turnover of solid engineers, often due to leadership losing focus on the product.</li></ul><p><strong>Actionable Insight</strong>: Consider hiring an OSINT professional to investigate why ex-employees left the company. Even with potential negativity bias, this can provide significant insights into the company&#39;s problems.</p><ul><li>Potential impacts of regulatory changes, such as the upcoming FTC non-compete dismissal, which might reveal underlying issues within companies.</li></ul><p><strong>Red Flags:</strong></p><ul><li>No mention of how the system will prevail against EW. Reliance on having a signal in an unknown/future environment.</li><li>Anything in a tube: Expensive and can&#39;t be easily modified, leading to an inability to adapt post-manufacture.</li><li>Testing environments where failure is bad for someone&#39;s career: If designed to look good or demonstrate readiness, it&#39;s a bad sign. If nobody invites EMS aggressors to try and stop it, it&#39;s a bad sign. If there&#39;s a grandstand with FOGOs watching, that&#39;s a demonstration - not a test.</li></ul>',32)])])}const g=t(o,[["render",s]]);export{m as __pageData,g as default};
